import { sensoryLessonDepth } from './lesson-depth-sensory'
import { vineLessonDepth } from './lesson-depth-vine'
import { cellarLessonDepth } from './lesson-depth-cellar'

export type GuideDepthLocale = 'en' | 'de' | 'fr' | 'es'
export type GuideDepthReading = Record<GuideDepthLocale, string[]>

const take = (reading: GuideDepthReading, indexes: number[]): GuideDepthReading => ({
  en: indexes.map((index) => reading.en[index]),
  de: indexes.map((index) => reading.de[index]),
  fr: indexes.map((index) => reading.fr[index]),
  es: indexes.map((index) => reading.es[index]),
})

const bottleAnatomyCore: GuideDepthReading = {
  en: [
    `Bottle families are historical solutions to making, moving and serving wine. Bordeaux shoulders, the sloping Burgundy profile and the tall Rhine flute are conventions, not universal containers for one taste. Their shapes reflect regional glassmaking, transport and sediment traditions, while producers may change format for cost, branding or lower packaging weight. Sparkling bottles are a special engineering case: thicker walls, a strong neck and a closure restrained by a cage are responses to internal pressure. The silhouette can tell you what handling problem the package was designed to solve; it cannot identify grape, quality or age on its own.`,
    `Shoulders become useful when a wine has sediment and the pour is controlled. Standing the bottle upright gives deposits time to settle; a slow pour toward a light lets the shoulder act as a visual stopping point before sediment reaches the glass. A sloped bottle does not make this impossible, but it changes the angle and may require a different cradle. Sediment is not automatically a fault: pigment, tannin and lees can precipitate during maturation. Taste the clear wine separately from the deposit and describe its condition before telling a story about filtration or authenticity.`,
    `The punt, or indentation at the base, has several possible functions: it can distribute stress, help a bottle stand, and give a hand a place to brace during pouring. Its depth is not a concentration meter. Heavy glass may be required for pressure or chosen for a premium visual signal, but it also adds transport emissions and handling weight. Compare two empty bottles by mass and wall thickness only to understand packaging. Never let a deep punt replace evidence from producer, origin, storage and the wine itself.`,
    `Neck finish, capsule and closure are part of bottle anatomy because they determine how the package is opened and sealed. A pushed cork, seepage around the capsule or a stained neck may indicate heat, pressure or storage trouble, but each sign needs context. For sparkling wine, inspect the cage, cork shape and glass for damage without shaking the bottle. A screw cap may look simple while its liner performs the critical seal. The visible bottle is therefore an inspection surface, not a complete record of the wine’s history.`,
    `Fill level and headspace are practical evidence. Compare ullage with bottle age, format, closure and known storage, remembering that large bottles, unusual shapes and fills from different producers are not directly interchangeable. A low level can suggest evaporation or a leak, yet it does not establish when the loss happened. Headspace affects the amount of gas above the liquid and can change development, but composition and temperature remain necessary variables. Record the observation, then state what you still need to know before opening or buying.`,
    `Formats change service and learning. A half bottle warms quickly and offers a different wine-to-headspace ratio; a magnum contains more liquid relative to its closure and can develop on another trajectory; a heavy prestige bottle may teach more about marketing than maturation. Before a purchase, ask whether the format suits the occasion, storage shelf, transport and waste goals. Before service, check stability, pressure, sediment and grip. The best bottle reading connects a physical feature to a function and refuses every quality claim that the feature cannot support.`,
  ],
  de: [
    `Flaschenfamilien sind historische Lösungen für Herstellung, Transport und Service. Bordeaux-Schulter, sanft abfallende Burgunderform und hohe Rheinflasche sind Konventionen und keine weltweiten Behälter für je einen Geschmack. Die Formen spiegeln regionale Glasherstellung, Transport und Depottradition; Erzeuger wechseln sie aber aus Kosten-, Marken- oder Gewichtsgründen. Schaumwein ist ein besonderer Ingenieursfall: dickere Wände, stabiler Hals und Drahtkorb reagieren auf Innendruck. Die Silhouette zeigt, welches Handhabungsproblem die Packung lösen sollte; Rebsorte, Qualität oder Alter liest du daraus nicht allein.`,
    `Schultern werden nützlich, wenn Wein Depot enthält und kontrolliert eingeschenkt wird. Aufrecht stehen lässt das Depot sinken; langsames Einschenken gegen Licht macht die Schulter zum sichtbaren Haltepunkt, bevor Sediment ins Glas gelangt. Eine schräge Flasche ist nicht unbrauchbar, verlangt aber einen anderen Winkel. Depot ist nicht automatisch ein Fehler: Pigment, Tannin und Hefen können bei Reife ausfallen. Trenne klaren Wein vom Depot und beschreibe den Zustand, bevor du eine Geschichte über Filtration oder Authentizität erzählst.`,
    `Der Punt am Boden kann Spannung verteilen, Standfestigkeit unterstützen und beim Einschenken als Griff dienen. Seine Tiefe misst keine Konzentration. Schweres Glas ist bei Druckflaschen eventuell nötig oder als Premiumsignal gewählt, erhöht aber Transportemissionen und Gewicht. Vergleiche leere Flaschen nur nach Masse und Wandstärke, um Verpackung zu verstehen. Lass einen tiefen Boden niemals Belege zu Erzeuger, Herkunft, Lagerung und Wein ersetzen.`,
    `Mündung, Kapsel und Verschluss gehören zur Flaschenanatomie, weil sie Öffnen und Abdichten bestimmen. Hochgedrückter Korken, Auslaufen unter der Kapsel oder Flecken am Hals können auf Hitze, Druck oder Lagerprobleme hindeuten, brauchen aber Kontext. Bei Schaumwein prüfst du Drahtkorb, Korkenform und Glas auf Schäden, ohne die Flasche zu schütteln. Eine Schraubkapsel wirkt schlicht, ihr Liner dichtet jedoch entscheidend. Die sichtbare Flasche ist eine Prüfoberfläche und kein vollständiges Geschichtsbuch.`,
    `Füllstand und Kopfraum sind praktische Belege. Vergleiche die Leere mit Alter, Format, Verschluss und bekannter Lagerung; große Flaschen, Sonderformen und Füllungen verschiedener Betriebe sind nicht direkt gleichzusetzen. Ein niedriger Stand kann Verdunstung oder Leck nahelegen, beweist aber nicht den Zeitpunkt. Kopfraum verändert die Gasmenge über der Flüssigkeit und damit Entwicklung, doch Zusammensetzung und Temperatur bleiben nötig. Notiere die Beobachtung und die Information, die dir vor Kauf oder Öffnen noch fehlt.`,
    `Formate verändern Service und Lernen. Eine Halbflasche wird schnell warm und hat ein anderes Wein-Kopfraum-Verhältnis; ein Magnum enthält relativ mehr Flüssigkeit und kann anders reifen; eine schwere Prestige-Flasche lehrt vielleicht mehr über Marketing als über Reife. Vor dem Kauf fragst du nach Anlass, Regal, Transport und Abfallziel. Vor dem Service prüfst du Stand, Druck, Depot und Griff. Gute Flaschenlektüre verbindet Merkmal und Funktion und verweigert jede Qualitätsbehauptung, die das Merkmal nicht tragen kann.`,
  ],
  fr: [
    `Les familles de bouteilles sont des solutions historiques pour produire, transporter et servir le vin. Épaules bordelaises, profil bourguignon incliné et flûte rhénane sont des conventions, non des récipients universels d’un goût. Leurs formes reflètent verrerie régionale, transport et habitudes liées au dépôt; un domaine peut les changer pour coût, marque ou réduction du poids. La bouteille effervescente relève d’une ingénierie particulière : verre épais, col robuste et muselet répondent à la pression interne. La silhouette indique une contrainte de manutention, pas cépage, qualité ou âge.`,
    `Les épaules servent lorsque le vin contient un dépôt et que le versement est maîtrisé. Laisser la bouteille debout aide le dépôt à descendre; verser lentement devant une lumière fait de l’épaule un repère visuel avant que les particules n’atteignent le verre. Une bouteille inclinée demande un autre angle mais fonctionne aussi. Le dépôt n’est pas automatiquement un défaut : pigments, tanins et lies peuvent précipiter avec l’âge. Séparez vin clair et dépôt et décrivez l’état avant de raconter une histoire sur filtration ou authenticité.`,
    `La piqûre au fond peut répartir les contraintes, aider la stabilité et offrir un appui pendant le service. Sa profondeur ne mesure pas la concentration. Un verre lourd peut être nécessaire pour la pression ou choisi comme signal de prestige, mais il augmente masse transportée et manutention. Comparez des bouteilles vides par masse et épaisseur seulement pour comprendre l’emballage. Une piqûre profonde ne remplace jamais les preuves du producteur, de l’origine, du stockage et du vin.`,
    `Col, capsule et fermeture appartiennent à l’anatomie parce qu’ils déterminent ouverture et étanchéité. Bouchon poussé, coulure sous la capsule ou tache au col peuvent évoquer chaleur, pression ou mauvaise conservation, mais chaque signe réclame du contexte. Pour un effervescent, examinez muselet, forme du bouchon et verre sans secouer. Une capsule à vis paraît simple alors que son joint assure l’étanchéité. La bouteille visible est donc une surface d’inspection, pas l’histoire complète du vin.`,
    `Niveau et espace de tête fournissent des indices pratiques. Comparez le vide à l’âge, au format, au bouchage et à la conservation connue, en vous rappelant que grands formats, formes spéciales et remplissages de domaines différents ne sont pas directement équivalents. Un niveau bas peut évoquer évaporation ou fuite sans dater la perte. L’espace de tête modifie le gaz au-dessus du liquide et son évolution, mais composition et température restent nécessaires. Notez l’observation et l’information manquante avant d’acheter ou d’ouvrir.`,
    `Les formats modifient service et apprentissage. Une demi-bouteille se réchauffe vite et présente un autre rapport vin-espace de tête; un magnum contient proportionnellement plus de vin et peut évoluer autrement; une bouteille lourde de prestige enseigne parfois davantage le marketing que la garde. Avant l’achat, demandez si le format convient à l’occasion, à l’étagère, au transport et aux déchets. Au service, vérifiez stabilité, pression, dépôt et prise en main. Lire une bouteille consiste à relier forme et fonction, jamais à inventer une qualité.`,
  ],
  es: [
    `Las familias de botellas son soluciones históricas para elaborar, mover y servir vino. Los hombros de Burdeos, el perfil inclinado de Borgoña y la botella alta del Rin son convenciones, no recipientes universales para un sabor. Sus formas reflejan vidrio regional, transporte y costumbres de sedimento, pero un productor puede cambiarlas por coste, marca o menor peso. El espumoso plantea una ingeniería especial: paredes gruesas, cuello resistente y bozal responden a la presión interna. La silueta indica qué problema de manejo debía resolver el envase; no identifica por sí sola variedad, calidad o edad.`,
    `Los hombros resultan útiles cuando hay sedimento y el vertido es controlado. Dejar la botella vertical permite que baje; servir lentamente frente a una luz convierte el hombro en un punto de parada antes de que las partículas lleguen a la copa. Una botella inclinada exige otro ángulo, pero también funciona. El sedimento no es automáticamente un defecto: pigmento, tanino y lías pueden precipitar durante la crianza. Separa vino claro y depósito y describe el estado antes de contar una historia sobre filtración o autenticidad.`,
    `El hueco de la base puede distribuir tensiones, ayudar a mantener la botella y ofrecer apoyo al servir. Su profundidad no mide concentración. El vidrio pesado puede ser necesario para presión o elegido como señal de lujo, pero aumenta masa transportada y esfuerzo. Compara botellas vacías por masa y grosor solo para entender el envase. Un fondo profundo nunca sustituye evidencia de productor, origen, conservación y vino.`,
    `Cuello, cápsula y cierre forman parte de la anatomía porque determinan apertura y sellado. Un corcho salido, fuga bajo la cápsula o mancha en el cuello pueden apuntar a calor, presión o mala guarda, pero cada señal necesita contexto. En espumosos, revisa bozal, forma del corcho y vidrio sin agitar. Una rosca parece sencilla, aunque su junta realiza el sellado crítico. La botella visible es una superficie de inspección, no el historial completo del vino.`,
    `Nivel de llenado y espacio de cabeza aportan evidencia práctica. Compara el vacío con edad, formato, cierre y conservación conocida, recordando que formatos grandes, formas especiales y llenados de productores distintos no son directamente equivalentes. Un nivel bajo puede sugerir evaporación o fuga, pero no dice cuándo ocurrió. El espacio de cabeza cambia el gas sobre el líquido y su evolución, aunque composición y temperatura siguen siendo variables necesarias. Registra la observación y lo que falta saber antes de comprar o abrir.`,
    `El formato cambia servicio y aprendizaje. Una media botella se calienta rápido y tiene otra relación entre vino y espacio de cabeza; un magnum contiene relativamente más líquido y puede evolucionar distinto; una botella pesada de prestigio quizá enseñe más sobre marketing que sobre madurez. Antes de comprar, pregunta si el formato encaja con ocasión, estantería, transporte y residuos. Antes de servir, comprueba estabilidad, presión, sedimento y agarre. Leer la botella es unir rasgo y función y rechazar cualquier afirmación de calidad que el rasgo no sostenga.`,
  ],
}

const dedicatedCore: Record<string, GuideDepthReading> = {
  'labels-and-origin': {
    en: [
      `A wine label has at least three layers: identity, legal origin and commercial invitation. Identity names the producer, bottler, wine, vintage, variety and volume; legal origin may be a country, protected geographical indication or appellation with a current specification; commercial language chooses what to make prominent. Read the back label before trusting the front. A château name, a négociant address and a bottling statement may describe different actors. Keep those roles separate when telling a guest who made the wine.`,
      `Origin terms work inside their own legal system. A French appellation can regulate grape varieties, yields and production, while an American AVA mainly establishes geographic boundaries and a German designation may combine origin with analytical or ripeness categories. None is a universal quality ladder. The same word can be protected in one market and promotional in another. When a label uses “reserve,” “old vines” or “estate,” ask which rule or producer record supports it, and say when no definition is available.`,
      `Vintage is evidence about a harvest, not a guarantee about every bottle from that year. Non-vintage wines can blend years intentionally for consistency, while a vintage wine may include local tolerances or legally permitted components. Alcohol, residual sugar, allergen and lot information add factual context but cannot predict balance. A place name can narrow provenance without telling you whether fruit was purchased, farmed by the named estate or assembled from several sites. Let the label establish what happened on paper, then let the glass test condition and style.`,
      `A practical label reading starts with a transcription. Write the exact producer, responsible bottler, origin, vintage, variety, alcohol, volume, lot and regulated category. Mark each as stated, inferred or missing. Then consult the current specification for the origin and compare it with the producer sheet. This method prevents a large front-label word from silently becoming a claim about soil, farming or quality. It also helps hosts explain uncertainty without sounding evasive: the label is precise about some facts and silent about others.`,
      `Use a variety-led Marlborough Sauvignon Blanc beside a place-led Bourgogne Pinot Noir to practise. Cover the fronts and recover the same facts from the remaining text, then taste both without reading tasting adjectives. Ask which label details predicted structure, which only established identity and which had no sensory test. Photograph and date the bottles because importer information and legal wording change. A useful label lesson ends with one next source to check and one question the bottle itself must answer.`,
      `Traceability is strongest when label language is connected to a lot and a responsible operator. A bottling address can distinguish wine bottled at the estate from wine bottled elsewhere, while an importer line explains the route into a market rather than the vineyard. Lot codes may help a producer investigate a complaint, but they rarely tell a taster how the wine will evolve. Record the language exactly, including punctuation and accents, and keep a photograph of both sides. When a translated back label adds a marketing phrase absent from the original, return to the original legal wording before presenting it as provenance.`,
      `For wine sold in the European Union, ingredient and nutrition rules began applying on 8 December 2023, with wines from the 2024 harvest covered while older production can remain exempt until stocks are exhausted. The ingredient list and nutrition declaration may be on the physical label or a dedicated electronic route such as a QR code; allergen information and energy value remain on the physical label. Treat the transition as market- and production-date-specific, not as a universal rule for every bottle worldwide, and check that an electronic page is clearly identified rather than a marketing link.`,
    ],
    de: [
      `Ein Weinetikett hat mindestens drei Ebenen: Identität, rechtliche Herkunft und kommerzielle Einladung. Zur Identität gehören Erzeuger, Abfüller, Wein, Jahrgang, Rebsorte und Füllmenge; die Herkunft kann Land, geschützte geografische Angabe oder Appellation mit aktueller Spezifikation sein; Werbung entscheidet nur über die Sichtbarkeit. Lies auch die Rückseite. Gutsname, Négociant-Adresse und Abfüllangabe können verschiedene Akteure meinen. Trenne diese Rollen, wenn du erklärst, wer den Wein gemacht hat.`,
      `Herkunftsbegriffe gelten innerhalb ihres eigenen Rechtssystems. Eine französische Appellation kann Sorten, Erträge und Verfahren regeln, eine amerikanische AVA vor allem Grenzen festlegen, und eine deutsche Bezeichnung Herkunft mit analytischer oder Reifekategorie verbinden. Keine davon ist eine weltweite Qualitätstreppe. „Reserve“, „alte Reben“ oder „Estate“ können geschützt oder frei verwendet werden. Frage, welche Regel oder Betriebsaufzeichnung den Anspruch trägt, und sage offen, wenn keine Definition auffindbar ist.`,
      `Der Jahrgang belegt eine Ernte, garantiert aber nicht jede Flasche dieses Jahres. Nichtjahrgangsweine können Jahre bewusst für Kontinuität verbinden; Jahrgangswein kann lokale Toleranzen und zulässige Bestandteile enthalten. Alkohol, Restzucker, Allergene und Losnummern liefern Fakten, sagen aber keine Balance voraus. Ein Ortsname schärft die Herkunft, erklärt jedoch nicht, ob Trauben gekauft, selbst angebaut oder aus mehreren Lagen verschnitten wurden. Lass das Etikett Papierfakten liefern und das Glas Zustand und Stil prüfen.`,
      `Beginne die Etikettenlektüre mit einer Abschrift. Notiere Erzeuger, verantwortlichen Abfüller, Herkunft, Jahrgang, Rebsorte, Alkohol, Füllmenge, Los und Kategorie. Markiere genannt, erschlossen oder fehlend. Prüfe anschließend die geltende Produktspezifikation und vergleiche sie mit dem Datenblatt. So wird ein großes Wort vorn nicht stillschweigend zum Beleg für Boden, Landwirtschaft oder Qualität. Ein Gastgeber kann dadurch Unsicherheit genau erklären: Das Etikett ist bei manchen Fakten präzise und bei anderen still.`,
      `Stelle einen sortenbetonten Marlborough Sauvignon Blanc neben einen ortsbetonten Bourgogne Pinot Noir. Verdecke die Vorderseite, rekonstruiere dieselben Fakten aus dem Rest und verkoste beide ohne Werbeadjektive. Frage, welche Angaben Struktur vorhersagten, welche nur Identität festlegten und welche im Glas keine Prüfung hatten. Fotografiere und datiere die Flaschen, da Importangaben und Rechtswörter wechseln. Eine gute Etikettenübung endet mit einer nächsten Quelle und einer Frage, die nur der Wein beantworten kann.`,
      `Rückverfolgbarkeit wird stärker, wenn Etikettenwörter mit Los und verantwortlichem Betrieb verbunden werden. Eine Abfülladresse kann Gutseinfllung von einer anderen Abfüllstelle unterscheiden; die Importzeile erklärt den Marktweg und nicht den Weinberg. Die Losnummer hilft einem Betrieb bei einer Reklamation, sagt aber selten, wie sich Wein entwickelt. Schreibe Wörter, Punkte und Akzente ab und fotografiere beide Seiten. Wenn eine Übersetzung einen Werbesatz ergänzt, der im Original fehlt, kehre vor einer Herkunftserzählung zum ursprünglichen Rechtstext zurück.`,
      `Für Wein im europäischen Unionsmarkt gelten seit dem 8. Dezember 2023 neue Angaben zu Zutaten und Nährwerten; Weine aus der Ernte 2024 fallen darunter, während ältere Erzeugnisse bis zum Abverkauf ausgenommen bleiben können. Zutatenliste und Nährwertdeklaration dürfen auf dem Etikett oder über einen eigens dafür bestimmten elektronischen Weg wie einen QR-Code stehen; Allergene und Energie bleiben auf dem physischen Etikett. Behandle den Übergang als abhängig von Markt und Produktionsdatum und nicht als weltweite Regel. Prüfe, ob die elektronische Seite klar als Information und nicht nur als Werbung gekennzeichnet ist.`,
    ],
    fr: [
      `Une étiquette de vin possède au moins trois couches : identité, origine légale et invitation commerciale. Identité signifie producteur, embouteilleur, cuvée, millésime, cépage et volume; l’origine peut être pays, indication protégée ou appellation dotée d’un cahier des charges; le marketing choisit la hiérarchie visuelle. Lisez le revers avant de croire la face avant. Nom de château, adresse de négociant et mention d’embouteillage peuvent désigner des acteurs différents. Séparez ces rôles lorsque vous présentez le vin.`,
      `Les termes d’origine fonctionnent dans leur propre système juridique. Une appellation française peut encadrer cépages, rendements et méthodes; une AVA américaine établit surtout des limites; une désignation allemande peut associer origine et catégorie analytique ou de maturité. Aucune n’est une échelle mondiale de qualité. « Réserve », « vieilles vignes » ou « estate » peuvent être définis dans un marché et libres ailleurs. Demandez quelle règle ou fiche du domaine confirme l’affirmation et signalez l’absence de définition.`,
      `Le millésime renseigne une récolte sans garantir chaque bouteille de l’année. Une cuvée non millésimée assemble volontairement plusieurs années; un vin millésimé peut inclure tolérances et composants autorisés. Alcool, sucre résiduel, allergènes et lot donnent un contexte factuel, pas un verdict d’équilibre. Un nom de lieu précise la provenance, mais ne dit pas si les raisins sont achetés, cultivés par le domaine ou assemblés. L’étiquette établit le papier; le verre doit encore tester état et style.`,
      `Commencez par transcrire l’étiquette. Notez producteur, embouteilleur responsable, origine, millésime, cépage, alcool, volume, lot et catégorie. Classez chaque donnée comme déclarée, déduite ou absente. Consultez ensuite le cahier des charges à jour et comparez-le à la fiche du domaine. Un mot mis en avant ne devient ainsi ni preuve de sol, ni preuve de viticulture, ni preuve de qualité. L’hôte peut expliquer précisément ce que l’étiquette sait et ce qu’elle ne dit pas.`,
      `Placez un sauvignon blanc de Marlborough centré sur le cépage à côté d’un pinot noir de Bourgogne centré sur le lieu. Masquez les faces avant, retrouvez les mêmes faits dans le reste du texte et goûtez sans adjectifs commerciaux. Demandez quelles données ont prédit la structure, lesquelles établissaient seulement l’identité et lesquelles n’avaient aucun test sensoriel. Photographiez et datez les bouteilles, car importateur et vocabulaire légal évoluent.`,
      `La traçabilité devient plus solide lorsque les mots de l’étiquette sont reliés à un lot et à l’opérateur responsable. Une adresse d’embouteillage peut distinguer la mise au domaine d’une mise faite ailleurs; la ligne d’importation décrit l’entrée sur un marché, non la parcelle. Le numéro de lot aide le domaine à enquêter sur une réclamation, mais prédit rarement l’évolution. Copiez ponctuation et accents et photographiez les deux faces. Si la traduction ajoute un argument commercial absent de l’original, revenez au texte légal avant d’en faire une histoire de provenance.`,
      `Pour les vins vendus dans l’Union européenne, les règles sur ingrédients et déclaration nutritionnelle s’appliquent depuis le 8 décembre 2023; les vins issus de la récolte 2024 sont concernés, tandis que les productions antérieures peuvent rester exemptées jusqu’à épuisement des stocks. La liste d’ingrédients et la nutrition peuvent figurer sur l’étiquette ou via un moyen électronique dédié, comme un QR code; allergènes et valeur énergétique restent sur l’étiquette physique. Présentez cette transition comme dépendante du marché et de la date de production, non comme une règle mondiale, et vérifiez que le lien électronique est informatif plutôt que publicitaire.`,
    ],
    es: [
      `Una etiqueta de vino tiene al menos tres capas: identidad, origen legal e invitación comercial. Identidad incluye productor, embotellador, vino, añada, variedad y volumen; el origen puede ser país, indicación geográfica protegida o denominación con pliego vigente; el marketing decide qué destaca. Lee la contraetiqueta antes de confiar en el frontal. Nombre de finca, dirección de négociant y mención de embotellado pueden referirse a actores distintos. Separa esos papeles al presentar el vino.`,
      `Los términos de origen funcionan dentro de su propio sistema legal. Una denominación francesa puede regular variedades, rendimientos y métodos; una AVA estadounidense establece sobre todo límites; una categoría alemana puede unir procedencia y condiciones analíticas o de madurez. Ninguna es una escala mundial de calidad. “Reserva”, “viñas viejas” o “estate” pueden estar definidos en un mercado y ser libres en otro. Pregunta qué norma o registro del productor sostiene el reclamo y declara si no hay definición.`,
      `La añada informa de una cosecha, pero no garantiza cada botella de ese año. Un vino sin añada puede mezclar años deliberadamente para continuidad; uno con añada puede incluir tolerancias y componentes permitidos. Alcohol, azúcar residual, alérgenos y lote aportan contexto factual, no un veredicto de equilibrio. Un nombre de lugar acota procedencia, pero no dice si la uva se compra, se cultiva en la finca o se mezcla de varios sitios. Deja que la etiqueta establezca el papel y que la copa pruebe estado y estilo.`,
      `Empieza transcribiendo la etiqueta. Escribe productor, embotellador responsable, origen, añada, variedad, alcohol, volumen, lote y categoría. Marca cada dato como declarado, inferido o ausente. Después consulta el pliego vigente y compáralo con la ficha del productor. Así una palabra grande del frontal no se convierte en evidencia de suelo, agricultura o calidad. El anfitrión puede explicar con precisión qué sabe la etiqueta y qué deja sin decir.`,
      `Coloca un Sauvignon Blanc de Marlborough centrado en variedad junto a un Pinot Noir de Bourgogne centrado en lugar. Tapa los frontales, recupera los mismos datos del resto y cata sin adjetivos publicitarios. Pregunta qué información predijo estructura, cuál solo estableció identidad y cuál no tuvo prueba sensorial. Fotografía y fecha las botellas, porque cambian importador y lenguaje legal.`,
      `La trazabilidad mejora cuando las palabras de la etiqueta se conectan con un lote y un operador responsable. Una dirección de embotellado puede distinguir la elaboración en finca de un embotellado externo; la línea del importador explica la entrada en un mercado, no la parcela. El lote permite investigar una reclamación, pero rara vez predice la evolución. Copia puntuación y acentos y fotografía ambos lados. Si la traducción añade marketing ausente del original, vuelve al texto legal antes de presentarlo como procedencia.`,
      `Para los vinos vendidos en la Unión Europea, las reglas sobre ingredientes y nutrición se aplican desde el 8 de diciembre de 2023; los vinos de la cosecha 2024 están incluidos, mientras que producciones anteriores pueden quedar exentas hasta agotar existencias. La lista de ingredientes y la declaración nutricional pueden aparecer en la etiqueta física o en un medio electrónico específico, como un código QR; alérgenos y valor energético permanecen en la etiqueta física. Explica la transición según mercado y fecha de producción, no como regla mundial, y comprueba que el enlace electrónico sea informativo y no solo publicidad.`,
    ],
  },
  'climate-and-altitude': {
    en: [
      `Altitude changes temperature, radiation and often wind, but it is not an independent flavour ingredient. Air drainage can make a valley floor colder than a slope at night; clouds and fog can reduce radiation; a ridge can lose water quickly even when average temperature is moderate. Measure the fruit zone rather than borrowing a number from a distant town. Latitude, continentality, ocean distance and altitude interact through season length, heat accumulation and frost risk. A site description is credible when it names the mechanism and time period instead of saying “high equals fresh.”`,
      `Day and night temperature are only part of the plant’s energy balance. Leaf area, row orientation, canopy density and soil water decide how much radiation is captured and how long stomata remain open. A cool site under water stress may stop photosynthesis earlier than a warmer irrigated site. Berry size, acidity, colour and tannin then move at different speeds. Taste these dimensions separately; a wine can have fresh acidity and ripe alcohol, or dark colour with hard seed tannin. Climate creates possibilities that farming and harvest decisions convert into fruit.`,
      `Ocean, river and fog moderate extremes but do not erase heat or disease risk. Wind can dry leaves and clusters, lowering fungal pressure while increasing transpiration; fog may cool the canopy and prolong wetness; a river can moderate temperature locally without controlling an entire appellation. Aspect changes the timing of sunlight, and slope position changes drainage and cold-air pooling. Use a site map and seasonal records before attaching a sensory claim to one geographic label.`,
      `A fair altitude trial compares Malbec from two parcels with similar grape, vintage and cellar method. Record elevation, aspect, wind, irrigation, soil depth, crop load, canopy and harvest date. Taste blind, separate structure from aroma and write predictions before revealing the sites. If a lower parcel is cooler at night or the wines are similar, that is not a failed experiment; it shows why altitude alone cannot explain style. Repeat in another year so one heatwave does not become a permanent regional stereotype.`,
      `Climate language should stay proportional to evidence. A long-term average describes possibility; a weather event describes one season; a producer decision explains how a parcel responded. Do not turn latitude, altitude or “diurnal range” into a promise of elegance. Ask which variable constrained ripening and which intervention changed it. The tasting note then becomes a testable link from energy and water to canopy, berry composition and cellar outcome.`,
      `Altitude also changes vineyard logistics. Steep parcels may drain cold air and receive different sunlight, yet they can be harder to prune, spray, harvest and irrigate. A later harvest at elevation may reflect access, labour or disease management rather than a simple temperature effect. Compare dates and interventions before attributing higher acidity or lower alcohol to height. When a producer reports elevation, ask whether it is the vineyard average, highest row or a rounded marketing number. Precision about the measurement keeps climate explanation tied to a real site.`,
    ],
    de: [
      `Höhe verändert Temperatur, Strahlung und oft Wind, ist aber kein eigenständiger Aromastoff. Kaltluft kann den Talboden nachts kälter machen als einen Hang; Wolken und Nebel mindern Strahlung; ein Rücken verliert Wasser schnell, auch bei mäßigem Mittel. Miss in der Traubenzone statt eine Zahl aus einer entfernten Stadt zu übernehmen. Breite, Kontinentalität, Meeresnähe und Höhe wirken über Saisonlänge, Wärmesumme und Frostrisiko zusammen. Gute Standortbeschreibung nennt Mechanismus und Zeitraum statt „hoch ist frisch“.`,
      `Tag- und Nachttemperatur sind nur Teile der Energiebilanz. Blattfläche, Zeilenrichtung, Laubdichte und Bodenwasser bestimmen Strahlungsaufnahme und wie lange Spaltöffnungen offen bleiben. Ein kühler trockener Standort kann Photosynthese früher bremsen als ein wärmerer bewässerter. Beerengröße, Säure, Farbe und Tannin reifen dann unterschiedlich schnell. Verkoste diese Dimensionen getrennt: Säure kann frisch und Alkohol reif sein, Farbe dunkel und Kerntannin hart. Klima eröffnet Möglichkeiten, Bewirtschaftung und Lese machen daraus Frucht.`,
      `Meer, Fluss und Nebel mildern Extreme, löschen aber Hitze- und Krankheitsrisiko nicht. Wind trocknet Blätter und Trauben, senkt Pilzdruck und erhöht Verdunstung; Nebel kühlt und verlängert Nässe; ein Fluss wirkt lokal. Exposition verändert den Zeitpunkt der Sonne, Hanglage Drainage und Kaltluft. Nutze Karte und Saisonprotokoll, bevor du einer geografischen Bezeichnung ein Aroma zuschreibst.`,
      `Ein fairer Höhenversuch vergleicht Malbec aus zwei Parzellen mit ähnlicher Rebe, Jahrgang und Kellerarbeit. Notiere Höhe, Exposition, Wind, Bewässerung, Bodentiefe, Ertrag, Laubwand und Lesetermin. Verkoste blind, trenne Struktur und Duft und schreibe Vorhersagen vor der Aufdeckung. Ist die tiefere Lage nachts kühler oder sind Weine ähnlich, ist der Versuch nicht gescheitert: Höhe allein erklärt den Stil nicht. Wiederhole in anderem Jahr, damit eine Hitzewelle kein ewiges Regionalbild wird.`,
      `Klimasprache muss zum Beleg passen. Mittelwerte zeigen Möglichkeiten, ein Wetterereignis eine Saison, eine Betriebsentscheidung die Reaktion einer Parzelle. Mache aus Breite, Höhe oder „Tagesgang“ kein Eleganzversprechen. Frage, was Reife begrenzte und welcher Eingriff es veränderte. Die Notiz verknüpft dann Energie und Wasser mit Laub, Beerenzusammensetzung und Kellerergebnis.`,
      `Höhe verändert auch die Arbeit im Weinberg. Steile Parzellen können Kaltluft ableiten und andere Sonne erhalten, sind aber schwerer zu schneiden, zu behandeln, zu lesen und zu bewässern. Eine späte Lese in der Höhe kann Zugang, Arbeitskräfte oder Krankheitsmanagement spiegeln und nicht nur Temperatur. Vergleiche Termine und Eingriffe, bevor du mehr Säure oder weniger Alkohol schlicht der Höhe zuschreibst. Frage, ob die Angabe Mittelwert, höchste Zeile oder gerundete Werbeziffer ist.`,
      `Notiere außerdem Messort und Messhöhe. Ein Sensor in der Wetterhütte, ein Datenlogger in der Laubwand und ein Satellitenwert beschreiben nicht dieselbe Temperatur. Wenn ein Betrieb „kühle Nächte“ sagt, frage nach Zeitraum, Minimum und Vergleichsstation. Diese kleine Quellenprüfung verhindert, dass ein einzelner Werbesatz zu einer Erklärung für Alkohol, Säure oder Duft wird.`,
    ],
    fr: [
      `L’altitude modifie température, rayonnement et souvent vent, mais n’est pas un arôme autonome. Le drainage de l’air peut rendre un fond de vallée plus froid qu’un coteau la nuit; nuages et brouillard réduisent le rayonnement; une crête perd vite son eau malgré une moyenne modérée. Mesurez la zone des grappes plutôt que d’emprunter le chiffre d’une ville éloignée. Latitude, continentalité, mer et altitude interagissent par durée de saison, chaleur accumulée et risque de gel. Une description sérieuse nomme mécanisme et période, pas « haut égale frais ».`,
      `Température du jour et de la nuit ne sont qu’une partie du bilan énergétique. Surface foliaire, orientation des rangs, densité de feuillage et eau du sol déterminent rayonnement et ouverture des stomates. Un site frais soumis au stress hydrique peut ralentir la photosynthèse avant un site plus chaud irrigué. Taille des baies, acidité, couleur et tanins évoluent alors à des vitesses différentes. Goûtez ces dimensions séparément : acidité fraîche et alcool mûr peuvent coexister. Le climat offre une possibilité que conduite et vendange transforment en fruit.`,
      `Mer, fleuve et brouillard modèrent les extrêmes sans supprimer chaleur ou maladies. Le vent sèche feuilles et grappes, réduit parfois les champignons mais augmente transpiration; le brouillard refroidit et prolonge l’humidité; un fleuve agit localement. Exposition, position sur la pente et accumulation d’air froid changent le calendrier. Utilisez carte et relevés saisonniers avant de transformer une étiquette géographique en arôme.`,
      `Un essai équitable compare deux parcelles de malbec avec cépage, millésime et méthode de cave proches. Notez altitude, exposition, vent, irrigation, profondeur, charge, feuillage et date de récolte. Goûtez à l’aveugle, séparez structure et arôme et écrivez les prédictions avant de révéler les lieux. Si la parcelle basse est plus fraîche la nuit ou si les vins se ressemblent, l’essai montre simplement que l’altitude seule ne dicte pas le style. Répétez une autre année.`,
      `Le vocabulaire climatique doit rester proportionné. Une moyenne longue décrit une possibilité, un événement une saison, une décision de producteur la réponse d’un lieu. Ne transformez pas latitude, altitude ou amplitude thermique en promesse d’élégance. Demandez quelle variable limitait la maturité et quelle intervention l’a modifiée. La note relie ainsi énergie, eau, feuillage, baie et vin fini.`,
      `L’altitude modifie aussi la logistique de la vigne. Une parcelle raide peut drainer l’air froid et recevoir une lumière différente, tout en compliquant taille, traitements, récolte et irrigation. Une vendange tardive en hauteur peut refléter accès, main-d’œuvre ou gestion sanitaire plutôt qu’un simple effet thermique. Comparez dates et interventions avant d’attribuer acidité ou alcool à l’altitude. Demandez si le chiffre est une moyenne, la ligne la plus haute ou un arrondi marketing.`,
      `Notez aussi le lieu et la hauteur de mesure. Une station météo, un capteur dans la canopée et une donnée satellite ne décrivent pas la même température. Quand un domaine parle de nuits fraîches, demandez la période, le minimum et la station de comparaison. Ce contrôle de source empêche une phrase publicitaire de devenir l’explication unique de l’alcool, de l’acidité ou du parfum.`,
    ],
    es: [
      `La altitud cambia temperatura, radiación y a menudo viento, pero no es un ingrediente aromático independiente. El drenaje del aire puede hacer más frío el fondo del valle que una ladera por la noche; nubes y niebla reducen radiación; una cresta pierde agua aunque su media térmica sea moderada. Mide la zona de racimos en vez de copiar una cifra de otra localidad. Latitud, continentalidad, mar y altura interactúan mediante duración de estación, calor acumulado y riesgo de helada. Una descripción sólida nombra mecanismo y periodo, no “alto equivale a fresco”.`,
      `Temperatura diurna y nocturna son solo parte del balance energético. Superficie foliar, orientación de filas, densidad de copa y agua del suelo deciden radiación y apertura de estomas. Un sitio fresco con estrés hídrico puede frenar fotosíntesis antes que uno más cálido e irrigado. Tamaño de baya, acidez, color y tanino avanzan a ritmos distintos. Prueba esas dimensiones por separado: acidez fresca y alcohol maduro pueden coexistir. El clima ofrece posibilidades que manejo y vendimia convierten en fruta.`,
      `Mar, río y niebla moderan extremos sin borrar calor ni enfermedades. El viento seca hojas y racimos, puede bajar presión fúngica y aumenta transpiración; la niebla enfría y alarga humedad; un río actúa localmente. Orientación, posición en ladera y acumulación de aire frío cambian calendario. Usa mapa y registros de temporada antes de convertir una etiqueta geográfica en aroma.`,
      `Una prueba justa compara Malbec de dos parcelas con variedad, añada y método de bodega similares. Registra altura, orientación, viento, riego, profundidad, carga, copa y fecha de cosecha. Cata a ciegas, separa estructura y aroma y escribe predicciones antes de revelar los sitios. Si la parcela baja es más fría de noche o los vinos se parecen, el resultado enseña que la altura sola no fija el estilo. Repite en otro año para no convertir una ola de calor en estereotipo.`,
      `El lenguaje climático debe guardar proporción con la evidencia. Un promedio largo describe posibilidades, un episodio una temporada y una decisión del productor explica la respuesta de una parcela. No conviertas latitud, altura o amplitud térmica en promesa de elegancia. Pregunta qué variable limitó maduración y qué intervención la cambió. La nota enlaza energía y agua con copa, baya y vino terminado.`,
      `La altitud también cambia la logística del viñedo. Una parcela inclinada puede drenar aire frío y recibir otra luz, pero dificulta poda, tratamientos, vendimia y riego. Una cosecha tardía en altura puede reflejar acceso, mano de obra o sanidad y no solo temperatura. Compara fechas e intervenciones antes de atribuir acidez alta o menos alcohol a la altura. Pregunta si la cifra es media del viñedo, la fila más alta o un redondeo comercial.`,
      `Anota también el lugar y la altura de medición. Una estación meteorológica, un sensor en la copa y un dato satelital no describen la misma temperatura. Si el productor habla de noches frescas, pregunta por periodo, mínimo y estación de comparación. Esta comprobación evita que una frase comercial se convierta en explicación única de alcohol, acidez o aroma.`,
    ],
  },
  cellaring: {
    en: [
      `Temperature stability is the first cellar priority. Wine changes faster when repeatedly warmed and cooled, and large swings can stress the closure and the liquid. A moderately cool, steady room is safer than a cold cupboard that cycles beside a heating appliance. Darkness protects colour and aroma, especially in clear or lightly tinted bottles. Vibration matters mainly when it repeatedly moves sediment or accompanies poor storage; a bottle does not become ruined because someone carried it across a room. Measure or record the real conditions rather than trusting a display on the cellar door.`,
      `Humidity has a practical role but is not a universal cure. Moderate humidity can help a natural cork and preserve labels, while a damp, mouldy room damages cartons, capsules and air quality. Keep bottles away from leaks and direct light, allow air circulation and inspect closures periodically. Store formats so they cannot roll or fall, and keep heavy bottles where lifting is safe. Storage is a chain of small controls, not a decorative rack.`,
      `Drinking windows are hypotheses about composition, closure, vintage and storage. A tannic red may gain integration while a delicate aromatic white loses primary fruit; a sweet wine with acidity can develop differently from a low-acid one with similar sugar. Producer estimates are valuable context, not expiry dates. Open one bottle from a case, write what fruit, acidity, tannin, aroma and finish show, then revise the next opening date. Your own preference belongs in the record because the “peak” is partly a drinking purpose.`,
      `Bottle position should follow the closure and the task. A natural cork is commonly stored so it does not dry out, but a wet label or mouldy capsule signals poor conditions; a screw cap does not need rotation to stay sealed. Stand a mature bottle upright before service so sediment settles, then pour gently and taste a small sample before deciding on a decanter. Separate sediment removal from aeration. A fragile old bottle can fade while a young structured wine becomes clearer, so air is a choice, not a ritual.`,
      `Build a cellar inventory that can teach you. Record acquisition, merchant, price, vintage, format, closure, location, storage history, intended occasion and an estimated opening window. Keep multiples when comparison is the point, not because scarcity creates value. Schedule bottles around real meals and guests, then update the note after opening. This turns storage into a learning rhythm: stable conditions protect the wine, a small experiment reveals development and the next decision remains reversible.`,
    ],
    de: [
      `Temperaturstabilität ist die erste Kellerpriorität. Wein verändert sich schneller bei wiederholtem Erwärmen und Abkühlen; große Sprünge belasten Verschluss und Flüssigkeit. Ein mäßig kühler, gleichmäßiger Raum ist sicherer als ein kalter Schrank neben einer Heizung. Dunkelheit schützt Farbe und Duft, besonders in hellen Flaschen. Vibration zählt vor allem, wenn sie Depot ständig bewegt oder mit schlechter Lagerung verbunden ist; ein kurzer Transport ruiniert keinen Wein. Miss die tatsächlichen Bedingungen, statt einer Anzeige an der Kellertür zu vertrauen.`,
      `Feuchtigkeit hat eine praktische, aber begrenzte Rolle. Mittlere Feuchte kann Naturkork und Etikett helfen; ein nasser, schimmeliger Raum beschädigt Kartons, Kapseln und Luftqualität. Halte Flaschen von Lecks und Licht fern, sorge für Luftzirkulation und prüfe Verschlüsse regelmäßig. Lagere Formate so, dass nichts rollt oder fällt, und schwere Flaschen in sicherer Höhe. Lagerung ist eine Kette kleiner Kontrollen und kein Dekorationsregal.`,
      `Trinkfenster sind Hypothesen über Zusammensetzung, Verschluss, Jahrgang und Lagerung. Ein tanninreicher Rotwein kann Einbindung gewinnen, ein empfindlicher aromatischer Weißwein Primärfrucht verlieren; ein säurereicher Süßwein entwickelt sich anders als ein säurearmer mit gleichem Zucker. Erzeugerangaben sind Kontext und kein Verfallsdatum. Öffne eine Flasche aus der Kiste, notiere Frucht, Säure, Tannin, Duft und Abgang und verschiebe die nächste. Auch deine Vorliebe gehört ins Protokoll, denn „Höhepunkt“ hängt vom Zweck ab.`,
      `Die Flaschenposition folgt Verschluss und Aufgabe. Naturkork lagert meist so, dass er nicht austrocknet, doch nasses Etikett oder Schimmelkapsel zeigen schlechte Bedingungen; eine Schraubkapsel braucht kein Drehen. Stelle reife Flasche vor dem Service aufrecht, damit Depot sinkt, schenke langsam und entscheide nach einer kleinen Probe über die Karaffe. Depottrennung und Belüftung sind verschieden. Empfindliche alte Flasche kann schwächer werden, junger strukturierter Wein klarer: Luft ist Wahl und kein Ritual.`,
      `Baue ein Kellerinventar, das dich lehrt. Notiere Kauf, Händler, Preis, Jahrgang, Format, Verschluss, Standort, Lagergeschichte, Anlass und geschätztes Trinkfenster. Mehrere Flaschen kaufst du für Vergleich und nicht aus künstlicher Knappheit. Plane Öffnungen zu echten Mahlzeiten und aktualisiere die Notiz. So wird Lagerung ein Lernrhythmus: stabile Bedingungen schützen, ein kleiner Versuch zeigt Entwicklung und die nächste Entscheidung bleibt umkehrbar.`,
    ],
    fr: [
      `La stabilité thermique est la première priorité d’une cave. Le vin évolue plus vite lorsque la température monte et descend souvent, et de grands écarts sollicitent bouchage et liquide. Une pièce fraîche et régulière vaut mieux qu’un placard très froid près d’un radiateur. L’obscurité protège robe et arômes, surtout dans les bouteilles claires. Les vibrations comptent surtout lorsqu’elles déplacent le dépôt de façon répétée ou accompagnent une mauvaise conservation; un déplacement bref ne détruit pas le vin. Mesurez les conditions réelles plutôt que l’affichage de la porte.`,
      `L’humidité a un rôle pratique mais limité. Une humidité modérée peut préserver liège et étiquettes; une pièce humide et moisie abîme cartons, capsules et air. Éloignez les bouteilles des fuites et de la lumière, laissez circuler l’air et inspectez les fermetures. Rangez les formats pour éviter chute et roulement, et placez les lourds à une hauteur sûre. La garde est une chaîne de petits contrôles, non un décor.`,
      `Les fenêtres de dégustation sont des hypothèses sur composition, bouchage, millésime et stockage. Un rouge tannique peut gagner en intégration tandis qu’un blanc aromatique délicat perd son fruit primaire; un liquoreux acide évolue autrement qu’un vin doux moins acide. L’estimation du producteur informe sans fixer une date limite. Ouvrez une bouteille d’une caisse, notez fruit, acidité, tanin, arômes et finale, puis ajustez la suivante. Votre préférence appartient au registre, car l’apogée dépend de l’usage.`,
      `La position suit le bouchage et la tâche. Le liège naturel est souvent stocké pour ne pas sécher, mais étiquette mouillée ou capsule moisie signalent de mauvaises conditions; une capsule à vis n’a pas besoin de rotation. Placez une bouteille mûre debout avant service pour laisser descendre le dépôt, versez doucement et goûtez avant de décider une carafe. Séparer le dépôt et aérer sont deux buts. Un vieux vin fragile peut décliner quand un jeune structuré gagne en netteté : l’air est un choix, pas un rituel.`,
      `Construisez un inventaire qui vous apprend quelque chose. Notez achat, marchand, prix, millésime, format, bouchage, emplacement, stockage, occasion et fenêtre estimée. Gardez plusieurs bouteilles pour comparer, non parce que la rareté crée une valeur. Programmez les ouvertures autour de vrais repas puis corrigez la note. La cave devient un rythme d’apprentissage : conditions stables, petite expérience, décision suivante réversible.`,
    ],
    es: [
      `La estabilidad térmica es la primera prioridad de una bodega. El vino evoluciona más deprisa cuando sube y baja muchas veces, y los cambios grandes tensionan cierre y líquido. Una sala fresca y constante es mejor que un armario muy frío junto a una calefacción. La oscuridad protege color y aroma, sobre todo en botellas claras. La vibración importa principalmente si mueve sedimento de forma repetida o acompaña mala conservación; llevar una botella unos metros no la arruina. Registra las condiciones reales en vez de confiar en una pantalla.`,
      `La humedad tiene una función práctica, pero limitada. Una humedad moderada puede ayudar al corcho y conservar etiquetas; un cuarto húmedo y con moho daña cajas, cápsulas y aire. Aleja botellas de fugas y luz, deja circular aire y revisa cierres. Guarda los formatos para evitar caídas y coloca los pesados a una altura segura. La guarda es una cadena de pequeños controles, no un mueble decorativo.`,
      `Las ventanas de consumo son hipótesis sobre composición, cierre, añada y conservación. Un tinto tánico puede ganar integración mientras un blanco aromático pierde fruta primaria; un dulce con acidez evoluciona distinto de otro con igual azúcar y menos acidez. La estimación del productor es contexto, no caducidad. Abre una botella de la caja, registra fruta, acidez, tanino, aroma y final y reajusta la siguiente. Tu preferencia pertenece al registro, porque el “pico” depende del propósito.`,
      `La posición depende del cierre y de la tarea. El corcho natural suele guardarse de modo que no se seque, pero etiqueta mojada o cápsula con moho indican mala conservación; una rosca no necesita girarse. Deja una botella madura vertical antes de servir para que baje sedimento, vierte despacio y prueba antes de decidir usar decantador. Separar sedimento y airear son objetivos diferentes. Un vino viejo frágil puede apagarse mientras uno joven gana claridad: el aire es una elección, no un ritual.`,
      `Construye un inventario que te enseñe. Registra compra, tienda, precio, añada, formato, cierre, ubicación, conservación, ocasión y ventana estimada. Guarda varias botellas para comparar, no porque la escasez cree valor. Programa aperturas alrededor de comidas reales y actualiza la nota. Así la bodega se vuelve un ritmo de aprendizaje: condiciones estables protegen, un experimento pequeño muestra evolución y la siguiente decisión sigue siendo reversible.`,
    ],
  },
  'sparkling-service': {
    en: [
      `Carbon dioxide makes a sparkling bottle both a sensory system and a safety object. Cold wine holds gas more calmly, so chilling reduces foam and pressure release. Let a shaken bottle settle upright, dry the glass and exterior, keep the cork restrained and point away from people. Loosen the cage without losing your grip, rotate the bottle slowly and aim for a quiet sigh. A loud pop is not proof of quality; it is uncontrolled release.`,
      `Pouring is a balance between preserving pressure and giving aroma space. A narrow flute displays a bead but can restrict the nose; a sparkling tulip or white-wine glass gives more headspace. Tilt the glass and pour down the side, pause when foam rises, then top up. Use the same measured volume when comparing glasses. Detergent residue, perfume and a warm glass can distort the result before wine style enters the discussion.`,
      `Mousse, bead and texture are related but not identical. Observe how quickly foam forms, whether bubbles rise in a stream, how long the bead persists and whether the palate feels sharp, creamy or coarse. Pressure, glass cleanliness, temperature and pour height influence the visual display. Acidity, dosage, lees age and bottle development influence the taste. Do not turn bubble size into a universal score.`,
      `Traditional-method wine may show bread, nuts, autolytic creaminess and quiet persistence after bottle ageing; tank-method wine may emphasise floral fruit and a vivid bead; ancestral-method wine may retain fermentation variability. These are production routes, not quality rankings. Read the label and producer record, then test whether the glass shows the expected structure. A style can be well served in more than one glass.`,
      `Build a service experiment with one bottle, two glasses and two temperatures. Open safely, pour equal amounts, taste before swirling and revisit after ten minutes. Record aroma, pressure, mousse, acidity, sweetness, bitterness and warmth. If a glass shows less foam but more aroma, neither result is automatically better. The useful conclusion names the service condition that made the intended balance easiest to perceive.`,
      `Service also changes how a host manages time. Keep the bottle cold between pours without freezing the wine, refill smaller amounts when aroma is the teaching goal and use a clean glass for a second style rather than topping up a scented one. Check the first pour for unexpected sweetness, bitterness or oxidation before offering a full glass. If the mousse fades, ask whether the cause is temperature, glass residue, pour height or the wine’s own age. This turns a dramatic visual feature into an observation that can be explained and repeated.`,
    ],
    de: [
      `Kohlendioxid macht eine Schaumweinflasche zugleich zum Sinnessystem und Sicherheitsobjekt. Kalter Wein hält Gas ruhiger, Kühlung senkt Schaum und Druckfreisetzung. Lass eine geschüttelte Flasche aufrecht zur Ruhe kommen, trockne Glas und Außenfläche, halte den Korken und richte die Flasche weg von Menschen. Lockere den Drahtkorb mit sicherem Griff, drehe die Flasche langsam und ziele auf ein leises Seufzen. Ein Knall beweist keine Qualität, sondern unkontrollierte Freisetzung.`,
      `Einschenken balanciert Druckerhalt und Duftfreisetzung. Eine Flöte zeigt Perlage, kann aber die Nase einengen; Tulpe oder Weißweinglas bieten Kopfraum. Neige das Glas, schenke an der Wand ein, pausiere bei aufsteigendem Schaum und fülle nach. Für Gläservergleiche nutzt du gleiche Menge. Spülmittel, Parfüm und warmes Glas verfälschen das Ergebnis, bevor Stil eine Rolle spielt.`,
      `Mousse, Perlage und Textur sind verbunden, aber nicht identisch. Beobachte Schaumbildung, Aufstieg in Strömen, Dauer und ob der Gaumen scharf, cremig oder grob wirkt. Druck, Glasreinigung, Temperatur und Füllhöhe beeinflussen die Optik. Säure, Dosage, Hefelager und Flaschenentwicklung beeinflussen den Geschmack. Blasengröße ist keine allgemeine Punktzahl.`,
      `Traditioneller Schaumwein kann nach Flaschenreife Brot, Nuss, Hefecremigkeit und ruhige Länge zeigen; Tankwein betont vielleicht florale Frucht und lebhafte Perlage; nach alter Methode kann Gärvariabilität bleiben. Das sind Wege und keine Rangliste. Lies Etikett und Datenblatt und prüfe, ob das Glas die erwartete Struktur zeigt. Ein Stil kann in mehreren Gläsern gut erscheinen.`,
      `Baue einen Serviceversuch mit einer Flasche, zwei Gläsern und zwei Temperaturen. Öffne sicher, schenke gleich ein, rieche vor dem Schwenken und kehre nach zehn Minuten zurück. Notiere Duft, Druck, Mousse, Säure, Süße, Bitterkeit und Wärme. Zeigt ein Glas weniger Schaum, aber mehr Duft, ist kein Ergebnis automatisch besser. Die Schlussfolgerung nennt die Bedingung, unter der Balance am klarsten wurde.`,
      `Service verändert auch die Zeitplanung. Halte die Flasche zwischen den Gläsern kühl, schenke kleinere Mengen nach, wenn Duft gelernt werden soll, und nutze für einen zweiten Stil ein sauberes Glas. Prüfe den ersten Guss auf unerwartete Süße, Bitterkeit oder Oxidation, bevor du voll einschenkst. Wenn Mousse schwindet, frage nach Temperatur, Glasrückstand, Füllhöhe oder Alter des Weins. So wird ein auffälliges Bild zu einer wiederholbaren Beobachtung statt zu einem Qualitätsurteil.`,
    ],
    fr: [
      `Le dioxyde de carbone fait de la bouteille effervescente un système sensoriel et un objet de sécurité. Le vin froid retient mieux le gaz; le refroidissement limite donc mousse et dégagement. Laissez reposer une bouteille secouée, essuyez verre et bouteille, maintenez le bouchon et dirigez-la loin des personnes. Desserrez le muselet sans perdre la prise, tournez lentement et visez un soupir discret. Un bruit sec ne prouve pas la qualité : il signale une libération mal contrôlée.`,
      `Verser consiste à préserver la pression tout en donnant de l’espace aux arômes. Une flûte montre le cordon mais peut resserrer le nez; une tulipe ou un verre à blanc offre plus d’espace de tête. Inclinez le verre, versez sur la paroi, attendez si la mousse monte puis complétez. Mesurez le volume pour comparer. Détergent, parfum et verre chaud déforment l’expérience avant le style.`,
      `Mousse, bulles et texture sont liées sans être identiques. Observez vitesse de formation, montée en file, persistance et toucher vif, crémeux ou grossier. Pression, propreté, température et hauteur du versement modifient le visuel. Acidité, dosage, lies et évolution en bouteille modifient la bouche. La taille des bulles n’est pas une note universelle.`,
      `Un vin de méthode traditionnelle peut offrir pain, noix, crémeux d’autolyse et persistance calme; la cuve peut accentuer fruit floral et bulles vives; la méthode ancestrale conserve parfois une variabilité fermentaire. Ce sont des voies, pas un classement de qualité. Lisez l’étiquette et la fiche du producteur puis vérifiez la structure dans le verre. Un style peut être bien servi dans plusieurs formes.`,
      `Organisez un essai avec une bouteille, deux verres et deux températures. Ouvrez sans risque, versez des volumes égaux, sentez avant agitation et revenez après dix minutes. Notez arômes, pression, mousse, acidité, douceur, amertume et chaleur. Un verre qui montre moins de mousse mais plus de parfum ne gagne pas automatiquement. Concluez par la condition qui rendait l’équilibre le plus lisible.`,
      `Le service modifie aussi la gestion du temps. Gardez la bouteille fraîche entre les verres, versez de petits volumes lorsque le but est d’apprendre les arômes et utilisez un verre propre pour le style suivant. Vérifiez le premier service avant de remplir : douceur, amertume ou oxydation peuvent surprendre. Si la mousse diminue, examinez température, résidu du verre, hauteur de versement et âge du vin. Vous transformez ainsi un effet visuel en observation répétable plutôt qu’en verdict.`,
    ],
    es: [
      `El dióxido de carbono convierte la botella espumosa en sistema sensorial y objeto de seguridad. El vino frío retiene mejor el gas, por lo que enfriar reduce espuma y liberación de presión. Deja reposar una botella agitada, seca copa y botella, sujeta el corcho y apunta lejos de personas. Afloja el bozal sin perder agarre, gira lentamente y busca un suspiro. Un estallido no demuestra calidad: es liberación sin control.`,
      `Servir equilibra conservar presión y dar espacio al aroma. La flauta muestra el cordón pero puede estrechar la nariz; una tulipa o copa de blanco ofrece más espacio. Inclina la copa, vierte por la pared, espera si sube la espuma y completa. Usa volumen medido al comparar. Detergente, perfume y una copa caliente distorsionan el resultado antes de hablar de estilo.`,
      `Mousse, burbuja y textura están relacionadas, pero no son iguales. Observa rapidez, ascenso en hilos, duración y si el tacto es afilado, cremoso o tosco. Presión, limpieza, temperatura y altura del vertido cambian lo visual. Acidez, dosage, lías y evolución en botella cambian el gusto. El tamaño de la burbuja no es una puntuación universal.`,
      `Un vino de método tradicional puede mostrar pan, frutos secos, cremosidad de autólisis y persistencia; uno de tanque puede enfatizar fruta floral y burbuja viva; el método ancestral puede conservar variación fermentativa. Son rutas, no una escala de calidad. Lee etiqueta y ficha del productor y comprueba la estructura en copa. Un estilo puede servirse bien en varias copas.`,
      `Diseña un experimento con una botella, dos copas y dos temperaturas. Abre con seguridad, sirve cantidades iguales, huele antes de agitar y vuelve a probar a los diez minutos. Registra aroma, presión, mousse, acidez, dulzor, amargor y calor. Si una copa muestra menos espuma pero más aroma, ningún resultado es automáticamente mejor. Concluye qué condición hizo más legible el equilibrio.`,
      `El servicio también cambia la gestión del tiempo. Mantén la botella fría entre copas, sirve cantidades pequeñas cuando el objetivo sea aprender aromas y usa una copa limpia para el estilo siguiente. Comprueba el primer vertido antes de llenar: dulzor, amargor u oxidación pueden sorprender. Si la mousse desaparece, pregunta por temperatura, residuo del vidrio, altura del vertido o edad del vino. Así un efecto visual se convierte en observación repetible y no en veredicto de calidad.`,
    ],
  },
  'appellation-maps': {
    en: [
      `An appellation map is a legal and geographic document, not a portrait of flavour. First identify what the boundary defines: a protected designation may regulate place, varieties, yields and methods, while another geographic indication may chiefly reserve a name for fruit grown inside a perimeter. Read the specification beside the map. The line tells you where a claim may be made; it does not tell you that every slope, soil and cellar practice inside the line is the same. A host should name the rule before describing the landscape.`,
      `Scale and legend determine what a map can support. A regional overview can show rivers, elevation bands and neighbouring designations, but a small printed inset may hide parcels, enclaves or boundary changes. Check projection, north arrow, date, source and whether the line follows a river, road, cadastral limit or geological interpretation. Compare the current official map with an older guide only after recording its date. A disagreement may reflect a revised legal boundary or a different scale rather than a factual error.`,
      `Bordeaux, Burgundy, Mosel and an American AVA illustrate different naming logics. A Bordeaux communal or subregional name can sit inside a wider appellation hierarchy; a Burgundian village, premier cru or climat uses a dense parcel vocabulary; a Mosel designation combines place language with German category rules; an AVA primarily describes a defined American growing area. Do not translate these systems into one ranking. Ask what is protected, who administers it and which production limits accompany the place name.`,
      `Boundaries contain variation and can also cut across physical continuities. A slope may share exposure and bedrock with a neighbouring designation while different rules, ownership history or market language separate the wines. Conversely, one appellation can include valley floors, terraces and ridges with different frost, drainage and heat patterns. Use the map to form a question about a bottle—parcel, elevation, soil, vintage or farming—then seek the producer’s site information instead of making the map explain the whole palate.`,
      `Make a five-scale map exercise: mark a continent, country, protected region, commune or village, and named parcel where the system provides one. For each level write one claim the map can establish and one claim it cannot. Taste two bottles from adjacent but legally distinct areas, hiding the labels, and compare structure without guessing a rank. Reveal the sources afterward and record which differences were documented, which were plausible mechanisms and which remain open. That separation makes cartography useful without turning it into a tasting shortcut.`,
    ],
    de: [
      `Eine Appellationskarte ist ein rechtliches und geografisches Dokument, kein Aromaporträt. Kläre zuerst, was die Grenze bestimmt: Eine geschützte Ursprungsbezeichnung kann Ort, Sorten, Erträge und Verfahren regeln, während eine andere geografische Angabe hauptsächlich einen Namen für Trauben aus einem Umriss reserviert. Lies die Spezifikation neben der Karte. Die Linie sagt, wo ein Anspruch möglich ist; sie sagt nicht, dass Hang, Boden und Kellerarbeit innerhalb der Linie gleich sind. Nenne zuerst die Regel, dann die Landschaft.`,
      `Maßstab und Legende begrenzen die Aussage. Eine Regionalübersicht kann Flüsse, Höhenstufen und Nachbargebiete zeigen, aber ein kleiner Ausschnitt verbirgt Parzellen, Einschlüsse oder Grenzänderungen. Prüfe Projektion, Nordpfeil, Datum, Quelle und ob die Linie einem Fluss, Weg, Kataster oder geologischen Modell folgt. Vergleiche eine aktuelle amtliche Karte mit einem älteren Führer erst nach dem Datieren beider. Widerspruch kann eine Rechtsänderung oder einen anderen Maßstab spiegeln und keinen Irrtum.`,
      `Bordeaux, Burgund, Mosel und eine amerikanische AVA zeigen verschiedene Namenslogiken. Ein Bordeaux-Gemeinde- oder Untergebietsname liegt in einer größeren Hierarchie; Burgund nutzt dichte Begriffe für Dorf, Premier Cru und Climat; an der Mosel verbinden sich Ortswörter mit deutschen Kategorien; eine AVA bezeichnet vor allem ein festgelegtes amerikanisches Anbaugebiet. Übersetze diese Systeme nicht in eine Rangliste. Frage, was geschützt ist, wer verwaltet und welche Produktionsgrenzen zum Namen gehören.` ,
      `Grenzen enthalten Vielfalt und können physische Kontinuitäten schneiden. Ein Hang kann Exposition und Gestein mit dem Nachbargebiet teilen, während Regeln, Eigentumsgeschichte oder Marktbezeichnungen die Weine trennen. Umgekehrt kann eine Appellation Talboden, Terrasse und Rücken mit verschiedenen Frost-, Drainage- und Wärmemustern umfassen. Nutze die Karte für eine Flaschenfrage—Parzelle, Höhe, Boden, Jahrgang oder Bewirtschaftung—und suche danach Betriebsdaten, statt den ganzen Geschmack aus der Linie zu erklären.`,
      `Übe fünf Maßstabsebenen: Kontinent, Land, geschütztes Gebiet, Gemeinde oder Dorf und benannte Parzelle, sofern das System sie führt. Schreibe für jede Ebene eine Aussage, die die Karte belegt, und eine, die sie nicht belegt. Verkosten zwei Flaschen aus benachbarten, rechtlich getrennten Gebieten blind und vergleiche Struktur ohne Rangvermutung. Decke Quellen danach auf und trenne dokumentierte Fakten, plausible Mechanismen und offene Fragen. So wird Kartografie ein Werkzeug statt eine Abkürzung.`,
    ],
    fr: [
      `Une carte d’appellation est un document juridique et géographique, non un portrait aromatique. Identifiez d’abord ce que délimite la frontière : une appellation protégée peut encadrer lieu, cépages, rendements et méthodes, tandis qu’une autre indication réserve surtout un nom aux raisins d’un périmètre. Lisez le cahier des charges avec la carte. La ligne indique où une mention est possible; elle ne rend pas identiques pentes, sols et pratiques dans toute la zone. Nommez la règle avant de raconter le paysage.`,
      `L’échelle et la légende déterminent ce que la carte peut prouver. Une vue régionale montre fleuves, bandes d’altitude et voisins, mais un petit encart masque parcelles, enclaves ou changements de limites. Vérifiez projection, nord, date, source et nature de la limite : rivière, route, cadastre ou interprétation géologique. Comparez une carte officielle récente avec un ancien guide seulement après avoir daté les deux. Une divergence peut venir d’une révision légale ou de l’échelle, pas d’une erreur factuelle.`,
      `Bordeaux, Bourgogne, Moselle et une AVA américaine illustrent des logiques différentes. Un nom communal ou sous-régional bordelais s’inscrit dans une hiérarchie; la Bourgogne emploie village, premier cru et climat; la Moselle combine vocabulaire de lieu et catégories allemandes; une AVA décrit surtout une aire viticole américaine définie. Ne traduisez pas ces systèmes en classement unique. Demandez ce qui est protégé, qui administre et quelles règles de production accompagnent le nom.`,
      `Les frontières contiennent de la diversité et peuvent couper une continuité physique. Une pente peut partager exposition et roche avec la zone voisine, tandis que règlement, histoire foncière ou marché séparent les vins. À l’inverse, une appellation peut réunir fond de vallée, terrasse et crête, soumis à des risques de gel, drainage et chaleur différents. Utilisez la carte pour formuler une question—parcelle, altitude, sol, millésime ou conduite—puis cherchez la donnée du domaine au lieu d’expliquer tout le goût par la ligne.`,
      `Faites un exercice à cinq échelles : continent, pays, région protégée, commune ou village, puis parcelle nommée si le système en prévoit une. Pour chaque niveau, écrivez une affirmation que la carte établit et une qu’elle n’établit pas. Goûtez à l’aveugle deux bouteilles de zones voisines mais juridiquement distinctes et comparez leur structure sans les classer. Révélez ensuite les sources et séparez faits documentés, mécanismes plausibles et questions ouvertes. La carte devient ainsi un outil, non un raccourci sensoriel.`,
    ],
    es: [
      `Un mapa de denominación es un documento legal y geográfico, no un retrato del sabor. Identifica primero qué define el límite: una denominación protegida puede regular lugar, variedades, rendimientos y métodos, mientras otra indicación reserva sobre todo un nombre para uva de un perímetro. Lee el pliego junto al mapa. La línea dice dónde puede hacerse una afirmación; no dice que todas las laderas, tierras y prácticas dentro sean iguales. Nombra la norma antes de describir el paisaje.`,
      `La escala y la leyenda determinan qué puede demostrar un mapa. Una vista regional muestra ríos, bandas de altitud y zonas vecinas, pero un recuadro pequeño oculta parcelas, enclaves o cambios de límite. Comprueba proyección, norte, fecha, fuente y si la línea sigue río, camino, catastro o interpretación geológica. Compara el mapa oficial actual con una guía antigua solo después de fechar ambos. Una diferencia puede ser una revisión legal o de escala, no un error factual.`,
      `Burdeos, Borgoña, Mosela y una AVA estadounidense muestran lógicas de nombre distintas. Un nombre comunal o subregional bordelés vive dentro de una jerarquía; Borgoña usa vocabulario denso de pueblo, premier cru y climat; Mosela une palabras de lugar con categorías alemanas; una AVA describe principalmente un área vitícola estadounidense definida. No traduzcas esos sistemas a una sola clasificación. Pregunta qué se protege, quién administra y qué límites productivos acompañan al nombre.`,
      `Los límites contienen variación y pueden cortar continuidades físicas. Una ladera puede compartir exposición y roca con la zona vecina, mientras normas, historia de propiedad o mercado separan los vinos. A la inversa, una denominación puede reunir valle, terraza y cresta con riesgos distintos de helada, drenaje y calor. Usa el mapa para formular una pregunta—parcela, altura, suelo, añada o manejo—y busca datos del productor en vez de hacer que la línea explique todo el paladar.`,
      `Haz un ejercicio de cinco escalas: continente, país, región protegida, municipio o pueblo y parcela nombrada si el sistema la reconoce. En cada nivel escribe una afirmación que el mapa prueba y otra que no prueba. Cata a ciegas dos botellas de áreas vecinas pero legalmente distintas y compara estructura sin adivinar una jerarquía. Después revela las fuentes y separa hechos documentados, mecanismos plausibles y preguntas abiertas. Así la cartografía sirve para investigar y no como atajo de cata.`,
    ],
  },
  'bottle-closures': {
    en: [
      `Natural cork is a biological material with a cellular structure, so its seal can vary from piece to piece. A sound cork can limit gas exchange while remaining elastic enough to grip the neck; a flawed or contaminated cork can leak, crumble or contribute musty taint. “Corked” describes a sensory problem associated with compounds such as TCA, not every wine opened with cork. Do not diagnose from the smell of the cork alone: taste the wine, compare a second bottle if possible and separate cork failure from heat damage, oxidation or reduction.`,
      `Technical corks combine cork granules or discs with binders and are manufactured for more consistent dimensions, while synthetic closures use polymers with their own permeability and ageing behaviour. A screw cap is a closure system, not one material: the liner, seal, torque and bottling operation control the interface with wine. Glass closures use a shaped stopper and gasket and may reduce some variability, but they still depend on filling, storage and handling. Compare the complete specification instead of ranking “cork” and “screwcap” as single categories.`,
      `The closure interacts with wine volume, headspace and temperature. A low fill may reflect evaporation or a leak; warm storage expands liquid and gas and can push a closure; a large headspace changes the starting oxygen load before any slow transfer through the seal. Inspect capsule, neck, seepage, cork height and bottle condition, then record the bottle’s age and storage history. A closure can be perfectly intact while the wine has oxidised from earlier exposure, so visible condition is evidence but not a verdict.`,
      `Opening technique protects both the wine and the clue you are trying to study. Cut the capsule cleanly, keep the bottle still, extract a natural cork without breaking it and smell the wine in the glass. For a screw cap, release the liner without treating the cracking sound as a quality signal. With sparkling wine, the crown cap used during production and the final mushroom cork serve different stages. Decanting, temperature and glass must be held steady if two closure systems are compared.`,
      `Run a closure trial with matched bottles from the same lot: keep one upright and one in the normal storage position only if the producer’s design makes that comparison meaningful, then open them at the same temperature. Taste immediately and again after an hour, tracking fruit, freshness, savoury notes, reduction, oxidation and finish. If one bottle differs, repeat before blaming the material. The useful conclusion states the observed variation, the plausible mechanism and the uncertainty that remains.`,
    ],
    de: [
      `Naturkork ist ein biologisches Material mit Zellstruktur, daher variiert die Dichtung von Stück zu Stück. Ein guter Kork begrenzt Gasaustausch und bleibt elastisch im Hals; ein fehlerhafter oder verunreinigter kann lecken, bröseln oder muffige Töne beitragen. „Korkig“ bezeichnet ein sensorisches Problem, oft mit Verbindungen wie TCA, und nicht jeden Wein unter Kork. Diagnostiziere nicht nur am Geruch des Korks: Probiere den Wein, vergleiche wenn möglich eine zweite Flasche und trenne Korkfehler von Hitze, Oxidation oder Reduktion.`,
      `Technische Korken verbinden Granulat oder Scheiben mit Bindemitteln und werden für gleichmäßigere Maße gefertigt; synthetische Verschlüsse nutzen Polymere mit eigener Durchlässigkeit und Reife. Eine Schraubkapsel ist ein System, kein einzelner Stoff: Liner, Dichtung, Drehmoment und Abfüllung bestimmen die Schnittstelle zum Wein. Glasverschlüsse nutzen Stopfen und Dichtung und können Streuung mindern, bleiben aber von Füllung, Lagerung und Umgang abhängig. Vergleiche die ganze Spezifikation und nicht die Schlagwörter Kork und Schraube.`,
      `Der Verschluss wirkt mit Füllstand, Kopfraum und Temperatur zusammen. Ein niedriger Stand kann Verdunstung oder Leck bedeuten; warme Lagerung dehnt Flüssigkeit und Gas aus und kann den Verschluss drücken; ein großer Kopfraum erhöht die anfängliche Sauerstofflast vor langsamem Transfer durch die Dichtung. Prüfe Kapsel, Hals, Auslaufen, Korkhöhe und Flaschenzustand und notiere Alter und Lagergeschichte. Intakter Verschluss schließt frühere Oxidation nicht aus: Sichtbares ist Hinweis, kein Urteil.`,
      `Die Öffnung schützt Wein und Diagnose. Schneide die Kapsel sauber, halte die Flasche ruhig, ziehe Naturkork ohne Bruch und rieche den Wein im Glas. Löse bei Schraubverschluss den Liner, ohne das Knacken als Qualitätszeichen zu werten. Beim Schaumwein dienen Kronkorken während der Herstellung und Pilzkorken am Ende verschiedenen Phasen. Wenn du Systeme vergleichst, halte Dekantieren, Temperatur und Glas gleich.`,
      `Führe einen Verschlussversuch mit gleichen Flaschen aus derselben Partie durch: Lagere eine nur dann aufrecht und eine normal, wenn die Konstruktion den Vergleich sinnvoll macht, und öffne beide gleich temperiert. Probiere sofort und nach einer Stunde und notiere Frucht, Frische, Würze, Reduktion, Oxidation und Abgang. Bei Unterschied wiederhole vor der Materialschuld. Das Ergebnis nennt Beobachtung, plausiblen Mechanismus und verbleibende Unsicherheit.`,
    ],
    fr: [
      `Le liège naturel est un matériau biologique à structure cellulaire; son étanchéité varie donc d’une pièce à l’autre. Un liège sain limite les échanges gazeux tout en restant élastique dans le col; un liège défectueux ou contaminé peut fuir, s’effriter ou apporter une odeur de moisi. « Bouchonné » décrit un problème sensoriel souvent lié à des composés comme le TCA, pas tout vin sous liège. Ne concluez pas sur l’odeur du bouchon seul : goûtez, comparez une seconde bouteille si possible et séparez défaut de liège, chaleur, oxydation et réduction.`,
      `Les bouchons techniques assemblent granulés ou disques de liège avec des liants pour obtenir des dimensions plus régulières; les synthétiques emploient des polymères dont perméabilité et évolution diffèrent. Une capsule à vis est un système : joint, liner, couple de serrage et embouteillage gouvernent l’interface avec le vin. Le verre utilise un bouchon moulé et un joint et peut réduire une part de variabilité, mais dépend encore du remplissage, stockage et transport. Comparez la fiche complète plutôt que les étiquettes « liège » et « vis ».`,
      `La fermeture interagit avec niveau, espace de tête et température. Un niveau bas peut signaler évaporation ou fuite; la chaleur dilate liquide et gaz et peut pousser le bouchage; un grand espace de tête augmente l’oxygène initial avant son transfert lent à travers le joint. Examinez capsule, col, coulure, hauteur du bouchon et état de la bouteille; notez âge et conservation. Une fermeture intacte n’exclut pas une oxydation antérieure : l’aspect est un indice, non une conclusion.`,
      `L’ouverture protège le vin et l’indice étudié. Découpez proprement la capsule, gardez la bouteille immobile, extrayez le liège sans le casser puis sentez dans le verre. Pour une vis, libérez le joint sans prendre le craquement pour un signe de qualité. Dans un effervescent, capsule couronne de production et bouchon champignon final ont des fonctions différentes. Pour comparer des fermetures, gardez carafe, température et verre identiques.`,
      `Organisez un essai avec des bouteilles appariées du même lot : ne mettez l’une debout et l’autre dans sa position habituelle que si le système le permet, puis ouvrez-les à température identique. Goûtez immédiatement et après une heure en suivant fruit, fraîcheur, notes savoureuses, réduction, oxydation et finale. Répétez avant d’accuser le matériau. La conclusion doit distinguer variation observée, mécanisme plausible et incertitude.`,
    ],
    es: [
      `El corcho natural es un material biológico con estructura celular, por lo que su sellado varía entre piezas. Un corcho sano limita el intercambio gaseoso y sigue siendo elástico en el cuello; uno defectuoso o contaminado puede gotear, desmenuzarse o aportar olor a moho. “Acorkado” describe un problema sensorial asociado a compuestos como TCA, no cualquier vino con corcho. No diagnostiques solo oliendo el corcho: prueba el vino, compara otra botella si puedes y separa fallo del cierre de calor, oxidación o reducción.`,
      `Los corchos técnicos combinan gránulos o discos con aglutinantes para lograr medidas más constantes; los sintéticos emplean polímeros con permeabilidad y evolución propias. Una cápsula de rosca es un sistema, no un material: junta, liner, par de apriete y embotellado controlan la interfaz con el vino. Los cierres de vidrio usan tapón y junta y pueden reducir variación, pero dependen igualmente de llenado, almacenamiento y manejo. Compara la especificación completa y no las etiquetas “corcho” y “rosca”.`,
      `El cierre interactúa con nivel, espacio de cabeza y temperatura. Un nivel bajo puede indicar evaporación o fuga; el calor dilata líquido y gas y puede empujar el cierre; un espacio de cabeza grande aumenta el oxígeno inicial antes de su transferencia lenta por la junta. Revisa cápsula, cuello, fugas, altura del corcho y estado de la botella y anota edad y conservación. Un cierre intacto no descarta oxidación anterior: el aspecto es evidencia, no veredicto.`,
      `La apertura protege el vino y la pista que estudias. Corta la cápsula limpiamente, mantén la botella quieta, extrae el corcho natural sin romperlo y huele el vino en copa. En una rosca, libera la junta sin tratar el chasquido como señal de calidad. En espumoso, la chapa usada durante producción y el corcho de hongo final cumplen etapas distintas. Para comparar cierres, mantén iguales decantación, temperatura y copa.`,
      `Haz una prueba con botellas emparejadas del mismo lote: coloca una vertical y otra en su posición normal solo si el diseño hace útil la comparación y ábrelas a igual temperatura. Prueba al instante y después de una hora, siguiendo fruta, frescura, notas sabrosas, reducción, oxidación y final. Repite antes de culpar al material. La conclusión debe nombrar variación observada, mecanismo plausible e incertidumbre restante.`,
    ],
  },
  'oxygen-and-age': {
    en: [
      `Oxygen is a timeline, not a single event called “letting a wine breathe.” Fruit can meet oxygen during crushing, pressing and transfers; yeast and lees alter the redox environment during fermentation; wine then exchanges with headspace, vessel and closure before bottling. Once bottled, temperature, dissolved oxygen at filling, closure permeability and storage time interact. Put each observation on that timeline. A wine that smells brighter after ten minutes has shown a response to air in that condition, not a universal rule that more oxygen improves it.`,
      `Phenolics and aroma compounds make oxygen effects depend on composition. Oxygen can help polymerisation and integration in some tannic red wines, while excessive exposure can consume fresh fruit, darken colour in whites or create aldehydic notes. Sulfur dioxide and other protective choices slow reactions but do not freeze a wine. Reduction is a different problem: struck-match or rubber notes may ease with limited air, yet aggressive aeration can erase delicate aromas. Describe the sensory change first, then propose chemistry cautiously.`,
      `Vessel and closure set different oxygen opportunities. A barrel supplies a porous surface and a changing headspace; a tank may be more inert but still gain oxygen during pumping; a bottle begins with its filling conditions and the seal’s transfer rate. “Micro-oxygenation” is a managed technique, not a synonym for any barrel-aged wine, and oak flavour is not the same as oxygen exposure. When reading a producer’s method, separate vessel material, time, topping, transfers and closure rather than reducing the process to “more air.”`,
      `Headspace and service create short-term variables that are easy to confuse with ageing. A half-full bottle has a larger wine-to-air ratio than a full one; swirling increases contact at the glass; decanting increases surface area but also removes volatile compounds. Temperature changes volatility and reaction rate, so compare samples at the same temperature. Taste a small pour before deciding to decant an old bottle: separating sediment is a mechanical task, while aerating is a chemical and aromatic gamble.`,
      `Design a three-point oxygen trial: taste immediately, after fifteen minutes and after an hour from the same bottle, keeping one sample covered and another in a clean glass. Record colour, fruit, floral notes, savoury character, acidity, tannin, bitterness and finish, not only “opened up.” Repeat with a younger structured red and a delicate aromatic white. The lesson is the curve: each wine has a useful exposure range, and the best service decision is the one supported by its actual response.`,
      `Dissolved oxygen is not identical to the air above a bottle. A winery can measure oxygen during filling, but a taster usually sees only its consequences: browning, muted fruit, volatile aldehydes or a change in sulfur character. Keep the sample history visible—how long the bottle was open, whether it was topped up, and whether the glass was rinsed—because an unclean glass can add its own aromas. When comparing closures, use bottles with matching fill and storage, and treat a single bottle as evidence of one history rather than proof of a universal ageing curve.`,
    ],
    de: [
      `Sauerstoff ist eine Prozesslinie und kein einzelnes Ereignis namens „atmen lassen“. Traubenmost begegnet Luft beim Quetschen, Pressen und Umfüllen; Hefe und Trub verändern während der Gärung das Redoxmilieu; danach tauscht Wein mit Kopfraum, Gefäß und Verschluss aus, bevor er in die Flasche kommt. In der Flasche wirken Füllsauerstoff, Durchlässigkeit, Temperatur und Zeit zusammen. Ordne jede Beobachtung ein. Wenn Wein nach zehn Minuten heller duftet, beweist das nur eine Reaktion unter dieser Bedingung und keine Regel für mehr Luft.`,
      `Phenole und Aromastoffe machen die Sauerstoffwirkung abhängig von der Zusammensetzung. Luft kann bei manchem tanninreichen Rotwein Polymerisation und Einbindung fördern; zu viel verbraucht Frische, verdunkelt Weißwein oder erzeugt aldehydische Töne. Schwefeldioxid bremst Reaktionen, friert Wein aber nicht ein. Reduktion ist ein anderes Problem: Streichholz- oder Gummitöne können mit begrenzter Luft weicher werden, aggressive Belüftung löscht jedoch zarte Düfte. Beschreibe zuerst die Sinnesänderung und formuliere Chemie vorsichtig.`,
      `Gefäß und Verschluss eröffnen verschiedene Sauerstoffwege. Ein Fass hat poröse Oberfläche und wechselnden Kopfraum; ein Tank ist oft inert, kann aber beim Pumpen Luft aufnehmen; die Flasche beginnt mit Füllbedingungen und Übertragungsrate der Dichtung. Mikrooxygenation ist eine gesteuerte Technik und kein anderes Wort für Fassreife; Holzaroma ist nicht dasselbe wie Luftkontakt. Trenne beim Lesen eines Datenblatts Material, Zeit, Auffüllen, Umfüllen und Verschluss, statt alles als „mehr Luft“ zu beschreiben.`,
      `Kopfraum und Service erzeugen kurzfristige Variablen, die man leicht mit Alter verwechselt. Eine halbvolle Flasche hat mehr Luft im Verhältnis zum Wein; Schwenken vergrößert Kontakt im Glas; Dekantieren vergrößert Oberfläche und entfernt zugleich flüchtige Stoffe. Temperatur verändert Flüchtigkeit und Reaktion, daher müssen Proben gleich temperiert sein. Probiere einen kleinen Guss, bevor du alten Wein karaffierst: Depottrennung ist mechanisch, Belüftung ein chemisches und aromatisches Risiko.`,
      `Baue einen Dreipunktversuch: sofort, nach fünfzehn Minuten und nach einer Stunde aus derselben Flasche probieren; eine Probe abdecken, die andere im sauberen Glas lassen. Notiere Farbe, Frucht, Blüte, Würze, Säure, Tannin, Bitterkeit und Abgang statt nur „offener“. Wiederhole mit jungem strukturiertem Rotwein und empfindlichem Aromaweißwein. Die Kurve zählt: Jeder Wein hat einen sinnvollen Luftbereich, und die beste Entscheidung folgt seiner tatsächlichen Reaktion.`,
      `Gelöster Sauerstoff ist nicht dasselbe wie die Luft über der Flasche. Ein Betrieb kann beim Füllen messen, der Verkoster sieht meist nur Folgen: Bräunung, gedämpfte Frucht, aldehydische Düfte oder veränderten Schwefelton. Halte die Vorgeschichte sichtbar—Öffnungsdauer, Nachfüllen und gespültes Glas—denn ein unsauberes Glas bringt eigene Aromen ein. Vergleiche Verschlüsse mit gleichem Füllstand und gleicher Lagerung und behandle eine Flasche als eine Geschichte, nicht als Beweis für jede Reifekurve.`,
      `Auch der Zeitpunkt der Schwefelzugabe und die Fülltemperatur gehören in die Sauerstoffgeschichte. Ein frischer Schwefelschub kann vorübergehend andere Düfte maskieren, während Wärme Reaktionen beschleunigt. Notiere daher nicht nur „nach Luft besser“, sondern Zustand, Temperatur und Zeit seit dem Öffnen. So bleibt die Beobachtung wiederholbar und verwechselt kurzfristige Freisetzung nicht mit jahrelanger Reife.`,
    ],
    fr: [
      `L’oxygène suit une chronologie, ce n’est pas un événement unique appelé « faire respirer ». Le raisin rencontre l’air au foulage, au pressurage et lors des transferts; levures et lies modifient le milieu redox pendant la fermentation; puis le vin échange avec espace de tête, contenant et fermeture avant la bouteille. En bouteille, oxygène dissous, perméabilité, température et durée se combinent. Situez chaque observation. Un vin plus lumineux après dix minutes répond à cette condition, sans prouver que plus d’air est toujours bénéfique.`,
      `Phénols et molécules aromatiques rendent l’effet dépendant de la composition. L’oxygène peut favoriser polymérisation et intégration d’un rouge tannique, mais l’excès consomme le fruit frais, assombrit un blanc ou produit des notes aldéhydiques. Le dioxyde de soufre ralentit les réactions sans figer le vin. La réduction est différente : des notes de soufre peuvent s’atténuer avec un peu d’air, tandis qu’une aération forte efface des arômes délicats. Décrivez d’abord le changement sensoriel, puis proposez la chimie avec prudence.`,
      `Contenant et fermeture offrent des occasions d’oxygène différentes. Le fût possède surface poreuse et espace variable; la cuve peut être plus inerte mais prendre de l’air au pompage; la bouteille commence avec ses conditions de remplissage et le taux de transfert du joint. La micro-oxygénation est une technique réglée, pas un synonyme d’élevage sous bois; goût de chêne et exposition à l’air ne sont pas identiques. Séparez matériau, durée, ouillage, transferts et fermeture dans la fiche du domaine.`,
      `Espace de tête et service créent des variables brèves que l’on confond facilement avec l’âge. Une bouteille à moitié pleine offre plus d’air par volume de vin; agiter augmente le contact dans le verre; décanter augmente la surface tout en retirant des composés volatils. La température change volatilité et vitesse de réaction : comparez à température égale. Goûtez un petit verre avant de carafer un vieux vin : retirer le dépôt est mécanique, l’aération est un pari chimique et aromatique.`,
      `Faites un essai en trois temps : immédiatement, après quinze minutes et après une heure, avec le même vin; couvrez un échantillon et laissez l’autre dans un verre propre. Notez couleur, fruit, fleurs, notes savoureuses, acidité, tanin, amertume et finale plutôt que « ouvert ». Recommencez avec un rouge jeune structuré et un blanc aromatique fragile. La courbe compte : chaque vin possède une plage utile d’exposition, et le service doit suivre sa réponse réelle.`,
      `L’oxygène dissous n’est pas identique à l’air de l’espace de tête. Le chai peut le mesurer au remplissage, tandis que le dégustateur n’observe que ses conséquences : brunissement, fruit atténué, aldéhydes ou modification des notes soufrées. Gardez l’historique visible—durée d’ouverture, éventuel remplissage et propreté du verre—car un verre mal rincé ajoute ses propres odeurs. Pour comparer des fermetures, choisissez niveau et conservation comparables; une bouteille raconte une histoire et ne prouve pas une courbe universelle.`,
      `La date d’ajout du soufre et la température de remplissage appartiennent aussi à cette histoire. Un apport récent peut masquer temporairement certains arômes, tandis que la chaleur accélère les réactions. N’écrivez donc pas seulement « meilleur à l’air » : notez état, température et délai depuis l’ouverture. L’observation restera répétable et ne confondra pas libération brève et évolution de plusieurs années.`,
    ],
    es: [
      `El oxígeno es una línea temporal, no un único evento llamado “dejar respirar”. La uva encuentra aire durante estrujado, prensado y trasiegos; levaduras y lías cambian el entorno redox durante la fermentación; después el vino intercambia con espacio de cabeza, recipiente y cierre antes del embotellado. En botella interactúan oxígeno disuelto, permeabilidad, temperatura y tiempo. Sitúa cada observación en esa línea. Si huele más brillante tras diez minutos, solo responde a esa condición, no demuestra que más oxígeno siempre mejore el vino.`,
      `Fenoles y compuestos aromáticos hacen que el efecto dependa de la composición. El oxígeno puede favorecer polimerización e integración en ciertos tintos tánicos, pero el exceso consume fruta fresca, oscurece blancos o crea notas aldehídicas. El dióxido de azufre ralentiza reacciones, no congela el vino. La reducción es distinta: notas de cerilla o goma pueden aliviarse con aire limitado, mientras una aireación fuerte borra aromas delicados. Describe primero el cambio sensorial y propone la química con cautela.`,
      `Recipiente y cierre ofrecen oportunidades de oxígeno diferentes. La barrica tiene superficie porosa y espacio de cabeza cambiante; el depósito puede ser más inerte, pero gana aire al bombear; la botella empieza con sus condiciones de llenado y la tasa de transferencia de la junta. La microoxigenación es una técnica controlada, no sinónimo de crianza en barrica; sabor de roble y contacto con aire no son iguales. Separa material, tiempo, relleno, trasiegos y cierre al leer el método del productor.`,
      `El espacio de cabeza y el servicio crean variables breves que se confunden con la edad. Una botella medio llena tiene más aire por volumen de vino; agitar aumenta el contacto en la copa; decantar aumenta superficie y también elimina compuestos volátiles. La temperatura cambia volatilidad y velocidad de reacción, así que compara a igual temperatura. Prueba un poco antes de decantar un vino viejo: separar sedimento es mecánico, airear es una apuesta química y aromática.`,
      `Diseña una prueba de tres momentos: prueba al instante, a los quince minutos y a la hora de la misma botella; cubre una muestra y deja otra en copa limpia. Registra color, fruta, flores, notas sabrosas, acidez, tanino, amargor y final, no solo “se abrió”. Repite con un tinto joven estructurado y un blanco aromático delicado. La curva enseña: cada vino tiene un intervalo útil de exposición y el servicio debe seguir su respuesta real.`,
      `El oxígeno disuelto no es igual que el aire sobre la botella. La bodega puede medirlo al llenar, pero el catador suele observar consecuencias: pardeamiento, fruta apagada, aldehídos o cambio de notas sulfurosas. Mantén visible la historia de la muestra—tiempo abierta, si se rellenó y si la copa estaba limpia—porque una copa mal enjuagada añade sus propios aromas. Al comparar cierres, iguala nivel y conservación y trata una botella como una historia, no como prueba de una curva universal de envejecimiento.`,
      `La fecha de la adición de sulfuroso y la temperatura de llenado también forman parte de la historia del oxígeno. Una adición reciente puede ocultar aromas durante un tiempo, mientras el calor acelera reacciones. No escribas solo “mejoró con aire”: anota estado, temperatura y tiempo desde la apertura. Así la observación se puede repetir y no confunde una liberación breve con evolución de años.`,
    ],
  },
}

